def rotate(a, direction):
 m,n=len(a),len(a[0]); out=[['.' for _ in range(m)] for _ in range(n)]
 for r in range(m):
  for c,ch in enumerate(a[r]):
   if direction=='cw': rr,cc=c,m-1-r
   else: rr,cc=n-1-c,r
   out[rr][cc]=ch
 return [''.join(row) for row in out]
